// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.List;

import org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativeCostVector.Feature;
import org.junit.jupiter.api.Test;

class LmdbNativeParallelVariantSelectionTest {

	@Test
	void elasticTwoWorkerCandidatePaysItsOwnBenefitCutRatherThanTheConfiguredEightWorkerCut() {
		LmdbNativeCandidate<String> serial = candidate("nestedLoop", 100_000_000D, 0);
		LmdbNativeCandidate<String> parallel = candidate("parallelPipelines", 65_000_000D, 2);
		LmdbNativeSelector.Ranking ranking = LmdbNativeSelector.rank(List.of(serial, parallel),
				LmdbNativeStaticPrior.DEFAULT, -1D, 8);
		assertThat(ranking.winner()).isEqualTo(1);
		assertThat(ranking.eliminatedBy()[1]).isNull();
	}

	@Test
	void aPackedVariantThatStartsWorkersCannotBypassTheParallelBenefitCut() {
		LmdbNativeCandidate<String> serial = candidate("nestedLoop", 100_000_000D, 0);
		LmdbNativeCandidate<String> parallel = candidate("packedFtree(workers=4)", 90_000_000D, 4);
		LmdbNativeSelector.Ranking ranking = LmdbNativeSelector.rank(List.of(serial, parallel),
				LmdbNativeStaticPrior.DEFAULT, -1D, 4);
		assertThat(ranking.winner()).isZero();
		assertThat(ranking.eliminatedBy()[1]).startsWith("Parallel");
	}

	@Test
	void synchronousChunkPipelineDoesNotPayAParallelBenefitCut() {
		LmdbNativeCandidate<String> serial = candidate("nestedLoop", 100_000_000D, 0);
		LmdbNativeCandidate<String> chunked = candidate("chunkPipeline", 90_000_000D, 0);
		LmdbNativeSelector.Ranking ranking = LmdbNativeSelector.rank(List.of(serial, chunked),
				LmdbNativeStaticPrior.DEFAULT, -1D, 4);
		assertThat(ranking.winner()).isEqualTo(1);
		assertThat(ranking.eliminatedBy()[1]).isNull();
	}

	private static LmdbNativeCandidate<String> candidate(String id, double scannedRows, int workers) {
		LmdbNativeCostQuote quote = new LmdbNativeCostQuote(
				LmdbNativeCostVector.point(Feature.WORKER_START, workers),
				LmdbNativeCostVector.point(Feature.SCANNED_ROW, scannedRows), 1D, false, false);
		return LmdbNativeCandidate.of(id, quote, () -> id);
	}
}
